    descriptionAdvanced: {
      de: "Der Bakuer Internationale Seehandelshafen in Alat, etwa 70 Kilometer südlich der aserbaidschanischen Hauptstadt, ist der wichtigste logistische Knotenpunkt am Kaspischen Meer. Er bildet das Herzstück des 'Trans-Caspian International Transport Route' (TITR) und verknüpft die Handelswege zwischen Europa und Asien. Geographisch profitiert der Hafen von seiner Lage an einer natürlichen Kreuzung von Eisenbahn- und Straßenverbindungen. Der Hafen wurde modernisiert, um riesige Mengen an Containern, Schüttgut und Ölprodukten abzuwickeln, wobei die erste Phase des neuen Terminals 2018 eröffnet wurde. Er spielt eine zentrale Rolle in der Diversifizierungsstrategie Aserbaidschans, um die Abhängigkeit vom Erdölsektor zu verringern und das Land als regionales Logistikzentrum zu etablieren. Mit einer Kapazität von Millionen Tonnen Fracht pro Jahr ist er ein entscheidender Faktor für die wirtschaftliche Integration Zentralasiens in den Weltmarkt. Der Hafen umfasst auch eine Freihandelszone (FEZ), die ausländische Investitionen anzieht.",
      hu: "A bakui nemzetközi tengeri kereskedelmi kikötő Alatban, az azerbajdzsáni fővárostól mintegy 70 kilométerre délre található, és a Kaszpi-tenger legfontosabb logisztikai központja. A kikötő a transzkaszpi nemzetközi szállítási útvonal (TITR) kulcsfontosságú eleme, amely összeköti az Európa és Ázsia közötti kereskedelmi útvonalakat. Földrajzi elhelyezkedése révén természetes csomópontot alkot a vasúti és közúti hálózatok találkozásánál. A modernizált kikötő első fázisát 2018-ban adták át, és hatalmas mennyiségű konténer, ömlesztett áru és kőolajtermék kezelésére alkalmas. Központi szerepet játszik Azerbajdzsán gazdasági diverzifikációs stratégiájában, amelynek célja az olajszektortól való függőség csökkentése és az ország regionális logisztikai központtá alakítása. Évente több millió tonna áruforgalmat bonyolít le, ezzel segítve Közép-Ázsia bekapcsolódását a világkereskedelembe. A kikötő területén különleges gazdasági övezet is működik, amely vonzza a külföldi befektetőket.",
      ro: "Portul Internațional de Comerț Maritim din Baku, situat în Alat, la aproximativ 70 km sud de capitala Azerbaidjanului, este cel mai important hub logistic de la Marea Caspică. Acesta reprezintă un punct nodal esențial pe Ruta de Transport Internațional Trans-Caspică (TITR), conectând fluxurile comerciale dintre Europa și Asia. Geografic, portul beneficiază de poziția sa strategică la intersecția principalelor rețele feroviare și rutiere regionale. Prima fază a noului terminal a fost inaugurată în 2018, fiind proiectată pentru a gestiona volume masive de containere, mărfuri generale și produse petroliere. Portul joacă un rol central în strategia de diversificare economică a Azerbaidjanului, reducând dependența de hidrocarburi și transformând țara într-un centru logistic regional. Cu o capacitate de procesare de milioane de tone anual, acesta facilitează integrarea Asiei Centrale în economia globală. Facilitatea include și o zonă economică liberă (FEZ) pentru a stimula investițiile străine.",
      en: "The Baku International Sea Trade Port at Alat, located about 70 kilometers south of Azerbaijan's capital, is the primary logistical gateway on the Caspian Sea. It serves as a cornerstone of the Trans-Caspian International Transport Route (TITR), linking trade networks between Europe and Asia. Geographically, the port is situated at a natural intersection of major rail and road corridors, enhancing its connectivity. The modern terminal's first phase opened in 2018, equipped to handle vast quantities of containers, bulk cargo, and petroleum products. The port is central to Azerbaijan's economic diversification strategy, aimed at reducing reliance on the oil sector and positioning the country as a regional logistics hub. With an annual capacity of millions of tons of cargo, it is a critical driver for the economic integration of Central Asian nations into the global market. The facility also features a Free Economic Zone (FEZ) designed to attract international business and foreign direct investment.",
      es: "El nuevo puerto marítimo internacional de Bakú, en la localidad de Alat, a unos 70 kilómetros al sur de la capital, es un nodo logístico central en la red comercial euroasiática. Desde su inauguración en 2018, se ha convertido en uno de los centros de transbordo más importantes del Mar Caspio. Forma parte esencial del corredor de transporte internacional TRACECA y de la iniciativa china 'Cinturón y Ruta de la Seda'. La instalación cuenta con terminales para transbordadores, carga general y Ro-Ro. Su ubicación estratégica permite una conexión directa con redes ferroviarias y de carreteras, acelerando el flujo de mercancías entre Asia y Europa y contribuyendo a la diversificación económica del país.",
      pt: "O novo Porto Marítimo Internacional de Baku, no povoado de Alat, cerca de 70 quilómetros a sul da capital, é um nó logístico central na rede comercial euroasiática. Desde a inauguração da primeira fase em 2018, o porto tornou-se um dos entrepostos mais importantes do Mar Cáspio. É parte integrante do corredor de transporte internacional TRACECA e da iniciativa chinesa 'Uma Faixa, Uma Rota'. A instalação inclui um terminal de ferries, um terminal de carga geral e um terminal Ro-Ro. A localização estratégica permite ligação direta às redes ferroviária e rodoviária, acelerando o fluxo de mercadorias entre a Ásia e a Europa.",
      fr: "Le nouveau port maritime international de Bakou, situé à Alat à environ 70 kilomètres au sud de la capitale, est un centre logistique central du réseau commercial eurasien. Depuis la mise en service de sa première phase en 2018, il est devenu l'un des principaux centres de transbordement de la mer Caspienne. Il fait partie intégrante du corridor de transport international TRACECA et de l'initiative chinoise 'La Ceinture et la Route'. L'installation comprend un terminal de ferry, un terminal de fret général et un terminal roulier (Ro-Ro). Son emplacement stratégique permet une connexion directe aux réseaux ferroviaires et routiers, accélérant le flux de marchandises entre l'Asie et l'Europe.",
    },
