      ro: ["Lungimea totală a conductei BTC este de exact 1.768 de kilometri.", "Inaugurarea oficială a proiectului a avut loc pe 13 iulie 2006.", "Capacitatea maximă de transport este de 1,2 milioane de barili pe zi.", "Conducta traversează 3 țări: Azerbaidjan, Georgia și Turcia.", "Cel mai înalt punct al traseului este la 2.830 de metri în Munții Caucaz.", "Costul total al construcției a fost de aproximativ 3,9 miliarde de dolari."],
      en: ["The total length of the BTC pipeline is exactly 1,768 kilometers.", "The official inauguration of the project took place on July 13, 2006.", "Maximum transport capacity is 1.2 million barrels of crude oil per day.", "The pipeline runs through 3 countries: Azerbaijan, Georgia, and Turkey.", "The highest point of the route is at 2,830 meters in the Caucasus.", "The construction cost of the pipeline was approximately 3.9 billion USD."],
